package echo

import (
	"fmt"
	"net/http"
	"testing"
	"time"
)

func findWithTimeout(t *testing.T, r *Router, e *Echo, method, path string) (res string) {
	done := make(chan string, 1)
	go func() {
		defer func() {
			if rec := recover(); rec != nil {
				done <- fmt.Sprintf("PANIC: %v", rec)
			}
		}()
		c := e.NewContext(nil, nil)
		r.Find(method, path, c)
		done <- "ok"
	}()
	select {
	case s := <-done:
		return s
	case <-time.After(300 * time.Millisecond):
		return "LOOP"
	}
}

func TestZZFuzzRouter(t *testing.T) {
	routeSets := [][]string{
		{"/a", "/b"},
		{"/a/:p", "/a/b"},
		{"/:p", "/a/b"},
		{"/a/*", "/a/:p"},
		{"/*", "/a"},
		{"/a/b/c", "/a/:p/d", "/a/*"},
		{"/:p/:q", "/a"},
		{"/a/:p", "/a/:p/c", "/a/*"},
		{"/", "/a"},
		{"/a/:p", "/a/:p/:q", "/a/b"},
		{"/users/create", "/users/:id/edit", "/users/:id/active"},
		{"/a/:p/c", "/a/:p/:q/c"},
	}
	paths := []string{"", "/", "//", "/a", "/a/", "/a/b", "/a/b/c", "/a/b/c/d", "/x", "/x/y", "/x/y/z", "/a//b", "a", "abc", "/a/b/c/d/e", "/users/createNotFound", "/a/b/", "/:p", "/a/:p"}
	for _, rs := range routeSets {
		e := New()
		r := e.router
		for _, rt := range rs {
			r.Add(http.MethodGet, rt, func(c Context) error { return nil })
		}
		for _, p := range paths {
			res := findWithTimeout(t, r, e, http.MethodGet, p)
			if res != "ok" {
				t.Errorf("routes=%v path=%q -> %s", rs, p, res)
			}
		}
	}
}
