package echo

import (
	"fmt"
	"math/rand"
	"net/http"
	"strings"
	"testing"
	"time"
)

func zzFind(e *Echo, method, path string) (res string) {
	done := make(chan string, 1)
	go func() {
		defer func() {
			if rec := recover(); rec != nil {
				done <- fmt.Sprintf("PANIC: %v", rec)
			}
		}()
		c := e.NewContext(nil, nil)
		e.router.Find(method, path, c)
		done <- "ok"
	}()
	select {
	case s := <-done:
		return s
	case <-time.After(200 * time.Millisecond):
		return "LOOP"
	}
}

func zzRandRoute(rnd *rand.Rand) string {
	n := 1 + rnd.Intn(4)
	parts := []string{}
	for i := 0; i < n; i++ {
		switch rnd.Intn(4) {
		case 0:
			parts = append(parts, "a")
		case 1:
			parts = append(parts, "b")
		case 2:
			parts = append(parts, ":p")
		case 3:
			parts = append(parts, "*")
		}
	}
	p := "/" + strings.Join(parts, "/")
	// truncate after any
	if idx := strings.Index(p, "*"); idx >= 0 {
		p = p[:idx+1]
	}
	return p
}

func zzRandPath(rnd *rand.Rand) string {
	n := rnd.Intn(5)
	parts := []string{}
	for i := 0; i < n; i++ {
		if rnd.Intn(3) == 0 {
			parts = append(parts, "")
		} else {
			parts = append(parts, []string{"a", "b", "c", "ab"}[rnd.Intn(4)])
		}
	}
	return "/" + strings.Join(parts, "/")
}

func TestZZFuzzRouter2(t *testing.T) {
	rnd := rand.New(rand.NewSource(42))
	for iter := 0; iter < 4000; iter++ {
		e := New()
		nr := 1 + rnd.Intn(5)
		routes := []string{}
		for i := 0; i < nr; i++ {
			rt := zzRandRoute(rnd)
			routes = append(routes, rt)
			e.router.Add(http.MethodGet, rt, func(c Context) error { return nil })
		}
		for j := 0; j < 6; j++ {
			p := zzRandPath(rnd)
			if res := zzFind(e, http.MethodGet, p); res != "ok" {
				t.Fatalf("routes=%v path=%q -> %s", routes, p, res)
			}
			if res := zzFind(e, http.MethodPost, p); res != "ok" {
				t.Fatalf("routes=%v path=%q POST -> %s", routes, p, res)
			}
		}
	}
}
EOF
