func zzReq(e *Echo, method, path string) (int, string) {
	req := httptest.NewRequest(method, path, nil)
	rec := httptest.NewRecorder()
	e.ServeHTTP(rec, req)
	return rec.Code, rec.Body.String()
}

func TestZZGroupSamePath(t *testing.T) {
	e := New()
	h := func(c Context) error { return c.String(http.StatusOK, "ok") }
	mk := func(name string) MiddlewareFunc {
		return func(next HandlerFunc) HandlerFunc {
			return func(c Context) error {
				c.Set("mw", c.Get("mw").(string)+name)
				return next(c)
			}
		}
	}
	hm := func(c Context) error { return c.String(http.StatusOK, c.Get("mw").(string)) }
	_ = h

	g1 := e.Group("/group", mk("1"))
	g1.GET("/help", hm)
	g2 := e.Group("/group", mk("2"))
	g2.GET("/help2", hm)
	g2.GET("/help", hm)

	t.Log(zzReq(e, http.MethodGet, "/group/help"))
	t.Log(zzReq(e, http.MethodGet, "/group/help2"))
	t.Log(zzReq(e, http.MethodGet, "/group/other"))
	t.Log(zzReq(e, http.MethodGet, "/group"))

	// nested groups
	e2 := New()
	g := e2.Group("/api", mk("a"))
	sg := g.Group("/v1", mk("b"))
	sg.GET("/x", hm)
	t.Log("nested:", zzReq(e2, http.MethodGet, "/api/v1/x"))
}

