func TestZZGroupUseDiffPaths(t *testing.T) {
	e := New()
	hm := func(c Context) error { v, _ := c.Get("mw").(string); return c.String(http.StatusOK, v) }
	mk := func(name string) MiddlewareFunc {
		return func(next HandlerFunc) HandlerFunc {
			return func(c Context) error {
				v, _ := c.Get("mw").(string)
				c.Set("mw", v+name)
				return next(c)
			}
		}
	}
	g1 := e.Group("/group")
	g1.Use(mk("1"))
	g1.GET("/a", hm)
	g2 := e.Group("/group")
	g2.Use(mk("2"))
	g2.GET("/b", hm)
	for _, p := range []string{"/group/a", "/group/b", "/group/c"} {
		req := httptest.NewRequest(http.MethodGet, p, nil)
		rec := httptest.NewRecorder()
		e.ServeHTTP(rec, req)
		t.Logf("%s -> %d %q", p, rec.Code, rec.Body.String())
	}
	// nested sub group middleware inheritance
	e2 := New()
	g := e2.Group("/api", mk("a"))
	sg := g.Group("/v1", mk("b"))
	sg.GET("/x", hm)
	req := httptest.NewRequest(http.MethodGet, "/api/v1/x", nil)
	rec := httptest.NewRecorder()
	e2.ServeHTTP(rec, req)
	t.Logf("nested -> %d %q", rec.Code, rec.Body.String())
}
